  "claim": {
    "component_id": "C041.component",
    "value": "The selected trial must cover several reconstructed late cases.",
    "scope": "Case-coverage requirement for trial selection; neither an exact count nor demonstrated generalization is supplied.",
    "provenance": {
      "refs": [
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P025 explicitly supplies the several-case coverage requirement for selecting a bounded trial."
    }
  },
  "signal_basis": {
    "component_id": "C041.signal_basis",
    "value": "A smaller configuration repeatedly reproduces lateness while specified further removals cease to reproduce it. This evidence concerns the selected case and need not explain the other late starts.",
    "scope": "Selected-case replay evidence motivating broader case coverage when choosing a trial.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P029",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the reproducing-reduction pattern, its selected-case scope, and the explicit limitation on explaining other late starts."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C041.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to warrant this prospective trial-selection requirement."
    }
  },
  "rationale": "The claim is a procedural coverage requirement. Given evidence restricted to a selected failure, requiring the trial to cover several reconstructed late cases is warranted as a safeguard against relying exclusively on that case. It does not assert that the observed reduction already explains those cases or establishes generalization.",
  "uncertainty": "The signal does not establish that any particular trial meets the requirement, and the mapping supplies no exact case count.",
  "anomalies": []
}
